<?php require '../config.php';$d=body();$token=$d['token']??'';$qid=(int)($d['question']??0);$selected=array_values(array_unique(array_map('intval',$d['answers']??[])));$s=db()->prepare("SELECT p.id player_id,p.game_id,q.time_limit,q.points,g.question_started_at FROM players p JOIN games g ON g.id=p.game_id JOIN questions q ON q.quiz_id=g.quiz_id AND q.id=? WHERE p.token=? AND g.status='question'");$s->bind_param('is',$qid,$token);$s->execute();$x=$s->get_result()->fetch_assoc();if(!$x)json_response(['error'=>'Frågan är stängd.'],409);$elapsed=max(0,(int)((microtime(true)-strtotime($x['question_started_at']))*1000));$correct=array_map('intval',array_column(db()->query('SELECT id FROM answers WHERE question_id='.$qid.' AND is_correct=1')->fetch_all(MYSQLI_ASSOC),'id'));sort($selected);sort($correct);$ok=$selected===$correct?1:0;$limit=(int)$x['time_limit']*1000;$speed=max(0,1-($elapsed/$limit));
// 50 % rätt svar, 35 % kvarvarande tid och 15 % placering bland de som svarar.
$gameId=(int)$x['game_id'];$answered=(int)db()->query('SELECT COUNT(*) c FROM responses WHERE game_id='.$gameId.' AND question_id='.$qid)->fetch_assoc()['c'];$participants=max(1,(int)db()->query('SELECT COUNT(*) c FROM players WHERE game_id='.$gameId)->fetch_assoc()['c']);$answerOrder=max(0,1-($answered/$participants));$points=$ok?(int)round((int)$x['points']*(0.5+0.35*$speed+0.15*$answerOrder)):0;$ids=implode(',',$selected);try{db()->begin_transaction();$s=db()->prepare('INSERT INTO responses(game_id,player_id,question_id,answer_ids,is_correct,response_ms,points_awarded) VALUES(?,?,?,?,?,?,?)');$s->bind_param('iiisiii',$x['game_id'],$x['player_id'],$qid,$ids,$ok,$elapsed,$points);$s->execute();$s=db()->prepare('UPDATE players SET score=score+? WHERE id=?');$s->bind_param('ii',$points,$x['player_id']);$s->execute();db()->commit();json_response(['ok'=>true]);}catch(mysqli_sql_exception $e){db()->rollback();json_response(['error'=>'Du har redan svarat.'],409);}
